export default function Icon({
  name,
  size = 20,
  color = 'currentColor',
  bold = false,
  variant,
  style = {},
  className = '',
  ...rest
}) {
  const IconComponent = TrueSightsIcons[name];
  if (!IconComponent) {
    console.warn(`Icon "${name}" not found in TrueSightsIcons registry.`);
    return null;
  }
  const resolvedVariant = variant || (bold ? 'bold' : 'linear');
  return (
    <IconComponent
      width={size}
      height={size}
      variant={resolvedVariant}
      bold={resolvedVariant === 'bold'}
      color={color}
      style={{ color, ...style }}
      className={className}
      {...rest}
    />
  );
}
